integratorSnippet.pseudo:
function storyForm12() {
  return state.questPack?.storyForm12 || state.storyForm12 || null;
}

function naturalAnyOk(clause) {
  if (!clause) return true;
  const day = state.save.dayIndex || 1;
  const alts = clause.naturalAny;
  if (!alts?.length) return whenFlagsOk(clause);
  if (clause.dayIndexMin != null && day < clause.dayIndexMin) return false;
  if (clause.flagsNone?.some((f) => storyFlag(f))) return false;
  return alts.some((alt) => whenFlagsOk(alt));
}

function applyNaturalArcStreetUnlock() {
  const sch = storyForm12()?.naturalUnlockSchedule;
  if (!sch) return;
  const day = state.save.dayIndex || 1;
  const flags = state.save.storyFlags;
  const antennaDone = (sch.volumeHeadphones.paths[0].antennaDoneAny || []).some(storyFlag);
  // Volume
  if (day >= 7 || (day >= 3 && antennaDone)) {
    flags.natural_volume_street = true;
  }
  // Ledger after volume street or calendar
  if (day >= 10 || (day >= 5 && (flags.natural_volume_street || ["arc_volume_war_complete","quest_volume_complete","arc_volume_war_beat5","street_av_handoff_done"].some(storyFlag)))) {
    flags.natural_ledger_street = true;
  }
  // one-layer: after volume has been shown 2+ days, prefer ledger
  if (flags.natural_ledger_street && day >= 10) {
    flags.natural_ledger_street_wins = true;
  }
}

function streetArcStagePropsHtml() {
  applyNaturalArcStreetUnlock();
  const f12 = storyForm12()?.naturalStreetProps || [];
  const f9 = (storyForm9()?.streetArcStageProps || []).filter(
    (p) => !f12.some((n) => n.replacesForm9Id === p.id || n.arcId === p.arcId)
  );
  const props = [...f12, ...f9];
  const coldShowing = isColdDay2();
  const hit = props
    .filter((p) => (p.screens || ["street"]).includes("street"))
    .filter((p) => p.unlockMode === "natural" ? naturalAnyOk(p.when || {}) : whenFlagsOk(p.when || {}))
    .filter((p) => !(coldShowing && p.arcId === "arc_kite_antenna"))
    .sort((a, b) => (b.priority || 0) - (a.priority || 0))[0];
  if (!hit) return "";
  return state.locale === "tr" && hit.htmlTr ? hit.htmlTr : hit.html || "";
}
